pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherCartel c;

    function setUp() public {
        c = new EtherCartel();
    }

    function _run(uint256 d) internal {
        vm.assume(d > 0);
        bool beforeInit;
        try c.initialized() returns (bool __r) { beforeInit = __r; } catch { return; }
        uint256 beforeMarket;
        try c.marketDrugs() returns (uint256 __r) { beforeMarket = __r; } catch { return; }
        try c.seedMarket(d) {} catch { return; }
        assertTrue(!beforeInit && beforeMarket == 0 && c.initialized() && c.marketDrugs() == d);
    }

    function testFuzz_run(uint256 d) public {
        _run(d);
    }

    receive() external payable {}
}
